CREATE TYPE "ProductType" AS ENUM ('COIN_PACKAGE','MEMBERSHIP','GOODS');
CREATE TYPE "OrderStatus" AS ENUM ('PENDING','PAID','CANCELLED','REFUNDING','REFUNDED');
CREATE TABLE "Product" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"type" "ProductType" NOT NULL,"price" INTEGER NOT NULL,"coinAmount" INTEGER,"planDays" INTEGER,"stock" INTEGER,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Product_pkey" PRIMARY KEY("id"));
CREATE TABLE "MembershipPlan" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"days" INTEGER NOT NULL,"price" INTEGER NOT NULL,"benefits" TEXT[],"active" BOOLEAN NOT NULL DEFAULT true,CONSTRAINT "MembershipPlan_pkey" PRIMARY KEY("id"));
CREATE TABLE "Membership" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"productId" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"startsAt" TIMESTAMP(3) NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Membership_pkey" PRIMARY KEY("id"));
CREATE TABLE "Address" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"recipient" TEXT NOT NULL,"phone" TEXT NOT NULL,"detail" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Address_pkey" PRIMARY KEY("id"));
CREATE TABLE "Order" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"productId" TEXT NOT NULL,"quantity" INTEGER NOT NULL,"totalAmount" INTEGER NOT NULL,"status" "OrderStatus" NOT NULL DEFAULT 'PENDING',"idempotencyKey" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Order_pkey" PRIMARY KEY("id"));
CREATE TABLE "PaymentEvent" ("id" TEXT NOT NULL,"orderId" TEXT NOT NULL,"eventId" TEXT NOT NULL,"success" BOOLEAN NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PaymentEvent_pkey" PRIMARY KEY("id"));
CREATE UNIQUE INDEX "Membership_userId_productId_key" ON "Membership"("userId","productId"); CREATE UNIQUE INDEX "Order_idempotencyKey_key" ON "Order"("idempotencyKey"); CREATE UNIQUE INDEX "PaymentEvent_eventId_key" ON "PaymentEvent"("eventId");
ALTER TABLE "Membership" ADD CONSTRAINT "Membership_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Membership" ADD CONSTRAINT "Membership_productId_fkey" FOREIGN KEY("productId") REFERENCES "Product"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "Address" ADD CONSTRAINT "Address_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Order" ADD CONSTRAINT "Order_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "Order" ADD CONSTRAINT "Order_productId_fkey" FOREIGN KEY("productId") REFERENCES "Product"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "PaymentEvent" ADD CONSTRAINT "PaymentEvent_orderId_fkey" FOREIGN KEY("orderId") REFERENCES "Order"("id") ON DELETE CASCADE ON UPDATE CASCADE;
